// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.InputStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.jar.Attributes;
import java.util.jar.Manifest;

import org.junit.jupiter.api.Test;

class LmdbOsgiManifestTest {

	@Test
	void generatedManifestUsesKnownJavaExecutionEnvironment() throws Exception {
		Path classesDirectory = Path
				.of(LmdbStore.class.getProtectionDomain().getCodeSource().getLocation().toURI());
		Path manifestPath = classesDirectory.resolve("META-INF/MANIFEST.MF");
		assertTrue(Files.isRegularFile(manifestPath), "LMDB classes must include the generated OSGi manifest");

		try (InputStream input = Files.newInputStream(manifestPath)) {
			Attributes attributes = new Manifest(input).getMainAttributes();
			String requiredCapabilities = attributes.getValue("Require-Capability");
			assertNotNull(requiredCapabilities, "The bundle must declare its Java execution environment");
			assertFalse(requiredCapabilities.contains("osgi.ee=UNKNOWN"), requiredCapabilities);
			assertTrue(requiredCapabilities.contains("osgi.ee=JavaSE"), requiredCapabilities);

			String importedPackages = attributes.getValue("Import-Package");
			assertNotNull(importedPackages);
			assertTrue(importedPackages.contains("jdk.incubator.vector;resolution:=optional"), importedPackages);
		}
	}
}
